const {chromium}=require('playwright'),fs=require('node:fs');
const base='https://chelovek-neiroset.ru',path='/case-ai-video-iz-foto/',url=base+path;
const title='Создание видео из фото с помощью ИИ — кейс Vikey AI',description='Кейс Vikey AI: создание двух AI-видео из исходных фотографий. Показываю формат «исходник → результат» и возможности нейросетей для динамичной подачи визуального материала.';
const routes=['/','/privacy','/sayty-dlya-biznesa/','/ii-assistent-dlya-biznesa/','/telegram-boty-dlya-biznesa/','/avtomatizaciya-biznesa-ai/','/ai-video-dlya-biznesa/','/upakovka-proekta/','/case-sayt-gostevye-domiki/','/case-b2b-horeca/','/case-ai-telegram-bot/','/case-cifrovoy-avatar/','/case-sayt-chastnogo-specialista/','/case-sayt-lichnogo-brenda/','/ai-kreativy-dlya-biznesa/',path];
const report={checkedAt:new Date().toISOString(),checks:{},devices:{},regressions:[],errors:[]};const check=(key,pass,data={})=>report.checks[key]={pass:!!pass,...data};
async function safe(key,fn){try{await fn()}catch(e){check(key,false,{error:String(e.message||e)});report.errors.push(key+': '+String(e.message||e))}}
async function run(){const browser=await chromium.launch({headless:true,args:['--no-sandbox']});try{const ctx=await browser.newContext();
try{
await safe('http',async()=>{const r=await ctx.request.get(url,{maxRedirects:0,timeout:35000});check('http',r.status()===200,{status:r.status()})});
await safe('redirect',async()=>{const r=await ctx.request.get(base+'/case-ai-video-iz-foto',{maxRedirects:0,timeout:35000});const loc=r.headers().location||'';check('redirect',[301,302,307,308].includes(r.status())&&(loc===path||loc===url),{status:r.status(),location:loc})});
await safe('sitemap',async()=>{const r=await ctx.request.get(base+'/sitemap.xml',{timeout:35000});const x=await r.text();const arr=[...x.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/g)].map(m=>m[1].trim());check('sitemap',r.status()===200&&arr.length===16&&arr.includes(url),{status:r.status(),count:arr.length,includesNew:arr.includes(url)})});
for(const [key,from,href] of [['homeToCase','/',path],['videoServiceToCase','/ai-video-dlya-biznesa/',path],['creativesToCase','/ai-kreativy-dlya-biznesa/',path],['caseToService',path,'/ai-video-dlya-biznesa/'],['caseToCreatives',path,'/ai-kreativy-dlya-biznesa/']])await safe(key,async()=>{const p=await ctx.newPage();try{const r=await p.goto(base+from,{waitUntil:'domcontentloaded',timeout:40000});const count=await p.locator('a').evaluateAll((els,target)=>els.filter(a=>a.getAttribute('href')===target).length,href);check(key,r.status()===200&&count>0,{status:r.status(),links:count})}finally{await p.close()}});
await safe('metadata',async()=>{const p=await ctx.newPage();try{const r=await p.goto(url,{waitUntil:'domcontentloaded',timeout:40000});const d=await p.evaluate(()=>({title:document.title,description:document.querySelector('meta[name="description"]')?.content||'',robots:document.querySelector('meta[name="robots"]')?.content||'',canonical:document.querySelector('link[rel="canonical"]')?.href||'',og:document.querySelector('meta[property="og:url"]')?.content||'',h1:[...document.querySelectorAll('h1')].map(x=>x.textContent.trim().replace(/\s+/g,' ')),faq:document.querySelectorAll('details').length,cta:!!document.querySelector('a[href="/#calc"]'),images:[...document.querySelectorAll('main img')].map(i=>i.currentSrc||i.src),manifest:!!document.querySelector('link[rel="manifest"]')}));check('metadata',r.status()===200);for(const [name,actual,want] of [['title',d.title,title],['description',d.description,description],['robots',d.robots,'index,follow'],['canonical',d.canonical,url],['ogUrl',d.og,url]])check(name,actual===want,{actual});check('h1',d.h1.length===1&&d.h1[0]==='Создание видео из фото с помощью ИИ',{actual:d.h1});check('faq',d.faq===6,{count:d.faq});check('cta',d.cta);for(const n of ['01','02']){check('source-'+n,d.images.some(s=>s.includes('ai-video-source-'+n)));check('poster-'+n,d.images.some(s=>s.includes('ai-video-result-'+n+'-poster')))}check('noPwaManifest',!d.manifest)}finally{await p.close()}});
for(const route of routes)await safe('regression '+route,async()=>{const r=await ctx.request.get(base+route,{timeout:35000});report.regressions.push({route,status:r.status(),pass:r.status()===200});check('regression '+route,r.status()===200)});
}finally{await ctx.close()}
for(const [name,w,h] of [['iPhone',390,844],['Android',412,915],['Desktop',1440,900]])await safe('device '+name,async()=>{const c=await browser.newContext({viewport:{width:w,height:h},isMobile:name!=='Desktop',hasTouch:name!=='Desktop',deviceScaleFactor:name==='Desktop'?1:3});const p=await c.newPage();const requests=[];p.on('request',r=>{if(r.url().includes('ai-video-result-')&&r.url().includes('.mp4'))requests.push(r.url())});try{await p.addInitScript(()=>{window.__cls=0;try{new PerformanceObserver(l=>{for(const e of l.getEntries())if(!e.hadRecentInput)window.__cls+=e.value}).observe({type:'layout-shift',buffered:true})}catch(e){}});const r=await p.goto(url,{waitUntil:'domcontentloaded',timeout:45000});await p.waitForTimeout(1700);const before=await p.evaluate(async()=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,cls:window.__cls||0,h1:document.querySelectorAll('h1').length,faq:document.querySelectorAll('details').length,footer:!!document.querySelector('footer'),cta:!!document.querySelector('a[href="/#calc"]'),images:[...document.querySelectorAll('main img')].map(i=>({src:i.currentSrc||i.src,ready:i.complete&&i.naturalWidth>0,width:i.getBoundingClientRect().width,screen:i.getBoundingClientRect().right<=innerWidth+1})),sw:'serviceWorker' in navigator?(await navigator.serviceWorker.getRegistrations()).length:0,initialVideos:document.querySelectorAll('video').length}));const noVideoBefore=requests.length===0&&before.initialVideos===0;let buttons=p.getByRole('button',{name:'Смотреть AI-видео'});const count=await buttons.count();let results=[];for(let i=0;i<Math.min(2,count);i++){const b=p.getByRole('button',{name:'Смотреть AI-видео'}).first();await b.click();const vid=p.locator('video').nth(i);const source=await vid.getAttribute('src');const videoData=await vid.evaluate(async v=>{v.muted=true;try{await v.play()}catch(e){}return {ready:v.readyState,playing:!v.paused,duration:v.duration,width:v.videoWidth,height:v.videoHeight}});results.push({source,videoData})}await p.waitForTimeout(1000);const refreshed=await p.reload({waitUntil:'domcontentloaded',timeout:45000});const imgs=before.images;const hasSource=imgs.filter(i=>i.src.includes('ai-video-source')).length>=2;const hasPosters=imgs.filter(i=>i.src.includes('ai-video-result-')&&i.src.includes('poster')).length>=2;const imageFit=imgs.every(i=>i.screen&&i.width>0);const ok=r.status()===200&&refreshed.status()===200&&!before.overflow&&before.cls<=0.1&&before.h1===1&&before.faq===6&&before.cta&&before.footer&&before.sw===0&&noVideoBefore&&count===2&&hasSource&&hasPosters&&imageFit&&results.length===2&&results[0].source.includes('result-01.mp4')&&results[1].source.includes('result-02.mp4')&&results.every(x=>x.videoData.width>0&&x.videoData.duration>0);report.devices[name]={pass:ok,status:r.status(),refresh:refreshed.status(),width:w,height:h,cls:before.cls,overflow:before.overflow,images:imgs,noVideoBefore,buttonCount:count,videoResults:results,requests,sw:before.sw};check('device '+name,ok,{summary:report.devices[name]})}finally{await c.close()}});
}finally{await browser.close()}}
(async()=>{try{await run()}catch(e){report.errors.push('fatal: '+String(e.stack||e))}finally{report.passed=Object.values(report.checks).length>=45&&Object.values(report.checks).every(v=>v.pass)&&report.regressions.length===routes.length&&Object.keys(report.devices).length===3&&report.errors.length===0;fs.writeFileSync('.github/ai-photo-video-live-report-temp.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,failed:Object.entries(report.checks).filter(([k,v])=>!v.pass).map(([k])=>k),errors:report.errors}));process.exitCode=report.passed?0:1}})();